public interface ShippingCost {
    int compute(int subtotal);
}

class StandardShipping implements ShippingCost {
    public int compute(int subtotal) {
        return 500;
    }
}

class FreeAbove100 implements ShippingCost {
    public int compute(int subtotal) {
        return subtotal >= 10000 ? 0 : 500;
    }
}

class Checkout {
    private final ShippingCost shipping;
    Checkout(ShippingCost shipping) {
        this.shipping = shipping;
    }
    int total(int subtotal) {
        return subtotal + shipping.compute(subtotal);
    }
}
